INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-01', 'gudumba-chaos-drop-tee-black', 'GUDUMBA® Chaos & Character Heavyweight Tee', 'Limited Drop 01 • Midnight Noir', 'A little chaos. A lot of character. Everyday streetwear.', 'Engineered with 280 GSM premium French terry combed cotton. Features the signature Gudumba insignia emblazoned in high-density puff print across the spine and minimalist chest emblem. Cut in an oversized, relaxed silhouette tailored for those who refuse to blend in.', 1899.0, 2499.0, 'cat-tees', true, false, '["280 GSM 100% Combed Compact Cotton","High-density screen + puff screen print","Drop-shoulder boxy oversized cut","Ribbed crewneck collar with reinforced tape","Pre-shrunk fabric to prevent post-wash deformation","Custom woven Gudumba interior label"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-02', 'gudumba-stay-strange-oversized-tee-white', 'GUDUMBA® Stay Strange Streetwear Tee', 'Editorial White • Raw Cut', 'For the ones who don''t blend in. Stay strange. Stay iconic.', 'Cut from premium 260 GSM organic milk cotton, this piece showcases the distinctive Gudumba industrial emblem. Built to make statements from Mumbai to London.', 1799.0, 2299.0, 'cat-tees', true, false, '["260 GSM Organic Milk Cotton","Distressed typography graphic backprint","Oversized drop-shoulder aesthetic","Double-needle stitching throughout","Anti-pilling wash finish"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-03', 'gudumba-unapologetic-terry-hoodie-rust', 'GUDUMBA® Unapologetic Heavy Hoodie', 'Earth & Rust Series', 'Born Different. Stay Unapologetic.', '450 GSM ultra-heavyweight brushed French terry cotton. Heavy metal hardware, double-lined deep hood, and seamless kangaroo pocket with concealed headphone port.', 3499.0, 4299.0, 'cat-hoodies', true, false, '["450 GSM Heavy French Terry Cotton","Double-layered structured hood (no drawstrings for clean silhouette)","Raglan sleeves with raw seam accents","Ribbed cuffs and waistband with 5% elastane memory retention"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-04', 'gudumba-editorial-campaign-bomber', 'GUDUMBA® No Rules Reversible Bomber Jacket', 'Exclusive Runway Edition', 'No rules. No repeats. Just pure attitude.', 'Structured tactical nylon shell with custom quilted inner orange lining. Features heavy-gauge gunmetal zippers, utility arm sleeve pocket, and custom embroidered back crest.', 5299.0, 6999.0, 'cat-drop1', true, false, '["High-density water-resistant technical flight nylon","Reversible safety-orange insulated diamond-quilted lining","Heavy-duty YKK matte black zippers","Custom woven Gudumba flight tag puller"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-05', 'gudumba-acid-wash-vintage-oversized-tee', 'GUDUMBA® Acid Wash Vintage Heavy Tee', 'Distressed Charcoal // Drop 01', 'Washed by fire. Worn with attitude.', '300 GSM vintage enzyme stone-washed cotton. Individual dye characteristics make each garment completely unique. Cut in our signature boxy oversized silhouette with ribbed neckline reinforcement.', 2199.0, 2899.0, 'cat-tees', true, false, '["300 GSM Enzyme Stone-Washed Cotton", "Vintage mineral distressed effect", "Pre-shrunk boxy cut", "Reinforced collar band"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-06', 'gudumba-tactical-wide-leg-cargo-pant', 'GUDUMBA® Japanese Twill Wide-Leg Cargo', 'Tactical Noir // Technical Series', 'Structured geometry for the streets.', 'Constructed from 340 GSM heavy Japanese cotton twill. Features 6 deep gusseted 3D utility cargo pockets, articulated knee darts, and adjustable bungee toggles at hem for versatile sneaker draping.', 4499.0, 5499.0, 'cat-bottoms', true, false, '["340 GSM Japanese Cotton Twill", "6 Gusseted 3D Cargo Compartments", "Articulated knee tailoring", "Hem bungee cinch cord"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-07', 'gudumba-monochrome-drop-shoulder-fleece', 'GUDUMBA® Core Minimalist Black Fleece', 'Obsidian // Essential Heavy', 'Understated luxury. Maximum presence.', '500 GSM heavyweight brushed loopback French terry. Clean seam construction, double-ply structured hood with no drawstrings, and tonal embroidered micro-monogram on forearm.', 3899.0, 4699.0, 'cat-hoodies', true, false, '["500 GSM Heavyweight Loopback Terry", "Tonal Gudumba forearm monogram", "Double-ply structured hood", "Hidden kangaroo pocket seams"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
INSERT INTO public.products (id, slug, name, subtitle, tagline, description, price, compare_at_price, category_id, is_featured, is_archived, details) VALUES ('prod-08', 'gudumba-utilitarian-tactical-vest', 'GUDUMBA® Modular Tactical Combat Vest', 'Armour Series // Runway Edition', 'Utility redefined. Pure attitude.', 'Heavy Cordura nylon canvas with waterproof taped inner seams. Features modular molle webbing, gunmetal carabiners, and dual front chest rig pockets.', 3999.0, 4999.0, 'cat-drop1', true, false, '["Cordura Nylon Canvas", "Molle modular webbing system", "Gunmetal industrial hardware", "Adjustable side compression straps"]'::jsonb) ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price;
